q("OFF-023",["kharidar","nasu","section-officer"],"Office Management & Public Service","Public Service Delivery","easy",2,"What is public service delivery?","Providing services by government offices to citizens","Selling goods in a private shop","Providing services only to officials","Collecting taxes only",0,"Public service delivery means government services such as certificates, permits and welfare reaching citizens.","Public administration")
